import{_ as t,o as p,c as e,a as r}from"./chunks/framework.Dj-71DD2.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"md/01-PDF批处理/450-批量解密pdf文件-并删除原文件.md","filePath":"md/01-PDF批处理/450-批量解密pdf文件-并删除原文件.md"}'),o={name:"md/01-PDF批处理/450-批量解密pdf文件-并删除原文件.md"};function n(i,a,s,l,d,h){return p(),e("div",null,[...a[0]||(a[0]=[r('<h2 id="_450-批量解密pdf文件-并删除原文件" tabindex="-1">450-批量解密pdf文件-并删除原文件 <a class="header-anchor" href="#_450-批量解密pdf文件-并删除原文件" aria-label="Permalink to &quot;450-批量解密pdf文件-并删除原文件&quot;">​</a></h2><p><img src="https://s2.loli.net/2024/12/12/EpxBTg3dGAvazKt.png" alt="image-20241021143614957"></p><p>批量解密pdf并删除原文件</p><p>比如A文件夹下有加密的pdf文件，同时有B、C、D…..等文件夹，文件夹下也有加密的pdf文件。</p><p>打开这个程序<img src="https://s2.loli.net/2024/12/12/OcsmRKlEXu8aFt9.png" alt="image-20241021143811282">，将A文件夹路径输入到程序中，</p><p>然后打开这个程序，进行pdf解密<img src="https://s2.loli.net/2024/12/12/OpYMEVCvNlUnx5r.png" alt="image-20241021143855323">，将所有pdf文件拖入到程序中，输出目录选择需要解密的pdf所在文件夹路径，</p><p>该程序不支持子文件夹穿透，需要逐个打开每个文件夹，将所有pdf拖入到程序中</p><p><strong>特别注意：不支持pdf打开密码解除</strong></p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多支持的文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有支持的文件。</p><p>只需要输入A文件夹和处理后输出的文件夹路径即可。</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统<br> 注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p>批量删除原文件，这个程序会持续监测A文件夹下所有文件变动，支持子文件夹穿透，保留解密后的文件，删除原文件，未加密的不会删除</p><p><img src="https://s2.loli.net/2024/12/12/Ja1OLg5pzEAilh8.png" alt="image-20241021144319947"></p><p>这个程序是批量解密pdf的程序，不支持子文件夹穿透</p><p><img src="https://s2.loli.net/2024/12/12/R1sc7OHSYBiThKp.png" alt="image-20241021144832961"></p><p>鼠标右键列表空白处点击即可选择清除pdf列表，重新点击文件</p><p><img src="https://s2.loli.net/2024/12/12/jREL2Anr1YZ59Ge.png" alt="image-20241021145040185"></p><h3 id="📑-视频演示" tabindex="-1">📑 视频演示 <a class="header-anchor" href="#📑-视频演示" aria-label="Permalink to &quot;📑 视频演示&quot;">​</a></h3><p><strong>视频链接【可点击链接查看视频】：</strong></p><h3 id="📑-win-mac程序定制说明" tabindex="-1">📑 win/mac程序定制说明 <a class="header-anchor" href="#📑-win-mac程序定制说明" aria-label="Permalink to &quot;📑 win/mac程序定制说明&quot;">​</a></h3><blockquote><p>程序定制微信：reset201901</p><p>1、明确自身需求，直入主题，简要描述；</p><p>2、我第一步想要怎样，第二步想要怎样...；</p><p>3、最终想要的结果是什么样的，自己能够清晰的描述出来,</p><p>4、最好是用txt文档将以上需求写清楚，或者录制视频将需求讲述清楚；</p><p>5、提供需要做测试的文件给我们，如果文件不便展示，可以创建一个txt文件将文件名后缀.txt修改为你同类型的文件即可。</p></blockquote><h3 id="📑-本工具下载地址" tabindex="-1">📑 本工具下载地址 <a class="header-anchor" href="#📑-本工具下载地址" aria-label="Permalink to &quot;📑 本工具下载地址&quot;">​</a></h3><p><strong>下载地址：</strong></p><p><a href="http://www.softbangong.top/?id=24" target="_blank" rel="noreferrer">http://www.softbangong.top/?id=24</a></p><hr><p>使用过程中如果有什么问题、新需求添加、新程序定制等，请添加微信沟通：reset201901</p><hr><h3 id="📑-友情提示" tabindex="-1">📑 友情提示 <a class="header-anchor" href="#📑-友情提示" aria-label="Permalink to &quot;📑 友情提示&quot;">​</a></h3><p><strong>正式使用前请先测试/备份原文件，然后再大批量使用，以免造成不可逆损失。</strong></p><hr><h3 id="📑-关注微信公众号不迷路" tabindex="-1">📑 关注微信公众号不迷路 <a class="header-anchor" href="#📑-关注微信公众号不迷路" aria-label="Permalink to &quot;📑 关注微信公众号不迷路&quot;">​</a></h3><p><img src="https://s2.loli.net/2024/11/02/tK9T7jxLcuv5rUk.png" alt="image"></p><blockquote><p>作者：极致办公 / 微信：reset201901</p></blockquote>',36)])])}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
